{% assign spec_table = product.metafields.custom.fairway_wood_spec_table.value %}
{% if spec_table %}
<style>
  .fw-spec-table-wrapper {
    overflow-x: auto;
    margin-top: 48px;
    -webkit-overflow-scrolling: touch;
  }

  .fw-spec-table {
    width: 100%;
    border-collapse: collapse;
    font-family: -apple-system, "Helvetica Neue", Helvetica, Arial, sans-serif;
    font-size: 12px;
    letter-spacing: 0.04em;
    color: #111;
  }

  .fw-spec-table thead tr {
    background: #000;
    border-bottom: 2px solid #000;
  }

  .fw-spec-table th {
    background: #000;
    color: #fff;
    padding: 14px 20px;
    text-align: left;
    font-weight: 500;
    font-size: 11px;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    white-space: nowrap;
  }

  .fw-spec-table th:first-child { padding-left: 24px; }
  .fw-spec-table th:last-child  { padding-right: 24px; }

  .fw-spec-table td {
    padding: 14px 20px;
    border-bottom: 1px solid #e8e8e8;
    color: #222;
    vertical-align: middle;
    white-space: nowrap;
    transition: color 0.2s ease;
  }

  .fw-spec-table td:first-child {
    padding-left: 24px;
    font-weight: 600;
    color: #000;
    font-size: 12px;
    letter-spacing: 0.08em;
    text-transform: uppercase;
  }

  .fw-spec-table td:last-child { padding-right: 24px; }

  .fw-spec-table tbody tr:nth-child(odd)  { background: #fff; }
  .fw-spec-table tbody tr:nth-child(even) { background: #fafafa; }

  .fw-spec-table tbody tr {
    transition: background 0.18s ease, box-shadow 0.18s ease;
  }

  .fw-spec-table tbody tr:hover {
    background: #f2f2f2;
    box-shadow: inset 3px 0 0 #000;
  }

  .fw-spec-table tbody tr:hover td { color: #000; }

  .fw-spec-table tbody tr:last-child td { border-bottom: none; }

  .fw-spec-footnote {
    margin-top: 10px;
    font-size: 11px;
    color: #888;
    letter-spacing: 0.02em;
    line-height: 1.5;
  }

  @media (max-width: 768px) {
    .fw-spec-table th,
    .fw-spec-table td {
      padding: 11px 12px;
      font-size: 11px;
    }

    .fw-spec-table th {
      font-size: 9px;
      letter-spacing: 0.09em;
    }

    .fw-spec-table td:first-child,
    .fw-spec-table th:first-child { padding-left: 14px; }

    .fw-spec-table td:last-child,
    .fw-spec-table th:last-child  { padding-right: 24px; }
  }
</style>

<div class="fw-spec-table-wrapper">
  <table class="fw-spec-table">
    <thead>
      <tr>
        <th>Head</th>
        <th>Loft</th>
        <th>Hand</th>
        <th>Lie</th>
        <th>Volume</th>
        <th>Length</th>
        <th>Swing Weight</th>
        <th>Club Weight</th>
      </tr>
    </thead>
    <tbody>
      {% for row in spec_table.rows.value %}
        <tr>
          <td>{{ row.head }}</td>
          <td>{{ row.loft }}</td>
          <td>{{ row.hand }}</td>
          <td>{{ row.lie }}</td>
          <td>{{ row.volume }}</td>
          <td>{{ row.length }}</td>
          <td>{{ row.swing_weight }}</td>
          <td>{{ row.club_weight }}</td>
        </tr>
      {% endfor %}
    </tbody>
  </table>
</div>

{% if spec_table.footnote != blank %}
  <p class="fw-spec-footnote">{{ spec_table.footnote }}</p>
{% endif %}

{% endif %}

{% assign shaft_tables = product.metafields.custom.woods_shaft_table.value %}
{% if shaft_tables %}
  <style>
    /*
     * SECTION WRAPPER
     * Generous top margin creates breathing room from surrounding content.
     */
    .shaft-specs {
      margin-top: 48px;
    }

    /*
     * SECTION TITLE
     * Tightened tracking and reduced weight (500 vs 700) for a more
     * editorial, less heavy-handed header feel.
     */
    .shaft-specs__title {
      font-family: -apple-system, "Helvetica Neue", Helvetica, Arial, sans-serif;
      font-weight: 500;
      font-size: 20px;
      letter-spacing: 0.12em;
      margin-bottom: 24px;
      text-transform: uppercase;
      text-align: center;
      color: #000;
    }

    /*
     * TABLE WRAPPER
     * Overflow-x retained for responsive safety.
     */
    .shaft-specs__table-wrap {
      overflow-x: auto;
      -webkit-overflow-scrolling: touch;
    }

    /*
     * TABLE BASE
     * Collapsed borders, refined font stack, base tracking cascades down.
     */
    .shaft-specs table {
      width: 100%;
      border-collapse: collapse;
      font-family: -apple-system, "Helvetica Neue", Helvetica, Arial, sans-serif;
      font-size: 14px;
      letter-spacing: 0.04em;
      color: #111;
      min-width: 520px;
    }

    /*
     * HEADER ROW
     * All-caps, wide tracking, medium weight — premium catalog aesthetic.
     * Black background anchors the table visually.
     */
    .shaft-specs thead tr {
      background: #000;
      border-bottom: 2px solid #000;
    }

    .shaft-specs th {
      background: #000;
      color: #fff;
      padding: 14px 20px;
      text-align: left;
      font-weight: 500;
      font-size: 12px;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      white-space: nowrap;
    }

    .shaft-specs th:first-child { padding-left: 24px; }
    .shaft-specs th:last-child  { padding-right: 24px; }

    /*
     * BODY CELLS
     * Generous vertical padding for breathing room. Light border guide.
     * First-child label cells elevated to create spec-name vs value hierarchy.
     */
    .shaft-specs td {
      padding: 14px 20px;
      border-bottom: 1px solid #e8e8e8;
      color: #222;
      vertical-align: middle;
      white-space: nowrap;
      transition: color 0.2s ease;
    }

    .shaft-specs td:first-child {
      padding-left: 24px;
      font-weight: 600;
      color: #000;
      font-size: 13px;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    .shaft-specs td:last-child { padding-right: 24px; }

    /*
     * ALTERNATING ROW TREATMENT
     * Near-imperceptible warm grey vs white — whispers structure, not spreadsheet.
     */
    .shaft-specs tbody tr:nth-child(odd)  { background: #fff; }
    .shaft-specs tbody tr:nth-child(even) { background: #fafafa; }

    /*
     * HOVER STATE
     * Inset left-edge accent via box-shadow (no layout shift).
     * Smooth transition — slides in, doesn't snap.
     */
    .shaft-specs tbody tr {
      transition: background 0.18s ease, box-shadow 0.18s ease;
    }

    .shaft-specs tbody tr:hover {
      background: #f2f2f2;
      box-shadow: inset 3px 0 0 #000;
    }

    .shaft-specs tbody tr:hover td { color: #000; }

    /*
     * LAST ROW
     * Remove dangling bottom border — table closes cleanly.
     */
    .shaft-specs tbody tr:last-child td { border-bottom: none; }

    /*
     * FOOTNOTE
     * Lightened and tightened — supporting text, not competing text.
     * Center-aligned preserved from original.
     */
    .shaft-specs__footnote {
      margin-top: 16px;
      font-family: -apple-system, "Helvetica Neue", Helvetica, Arial, sans-serif;
      font-size: 11px;
      line-height: 1.6;
      color: #888;
      letter-spacing: 0.03em;
      text-align: center;
    }

    /*
     * IMAGE BLOCK
     * Slightly more top margin to separate from table cleanly.
     */
    .shaft-specs__media { margin-top: 24px; }

    .shaft-specs__image-wrap {
      width: 100%;
      max-width: 900px;
      margin: 0 auto;
    }

    .shaft-specs__image {
      width: 100%;
      height: auto !important;
      max-width: 100%;
      object-fit: contain !important;
      display: block;
    }

    /*
     * IMAGE CAPTION
     * Matches title tracking and case — cohesive typographic system.
     */
    .shaft-specs__caption {
      margin-top: 12px;
      text-align: center;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      font-size: 10px;
      color: #999;
    }

    /*
     * RESPONSIVE BREAKPOINT
     * Reduced padding and tracking at mobile so columns stay visible longer.
     */
    @media (max-width: 768px) {
      .shaft-specs th,
      .shaft-specs td {
        padding: 11px 12px;
        font-size: 11px;
      }

      .shaft-specs th {
        font-size: 9px;
        letter-spacing: 0.09em;
      }

      .shaft-specs td:first-child,
      .shaft-specs th:first-child { padding-left: 14px; }

      .shaft-specs td:last-child,
      .shaft-specs th:last-child  { padding-right: 14px; }
    }
  </style>

  {% for shaft_table in shaft_tables %}
    <section class="shaft-specs">
      {% assign table_title = shaft_table.title | default: shaft_table.shaft | default: shaft_table.name %}
      {% if table_title != blank %}
        <h2 class="shaft-specs__title">{{ table_title }}</h2>
      {% endif %}
      <div class="shaft-specs__table-wrap">
        <table>
          <thead>
            <tr>
              <th>Flex</th>
              <th>Weight*</th>
              <th>Torque</th>
              <th>Tip Diameter</th>
              <th>Butt Diameter</th>
              <th>Launch</th>
              <th>Spin</th>
            </tr>
          </thead>
          <tbody>
            {% for row in shaft_table.rows.value %}
              <tr>
                <td>{{ row.flex }}</td>
                <td>{{ row.weight }}</td>
                <td>{{ row.torque }}</td>
                <td>{{ row.tip_diameter }}</td>
                <td>{{ row.butt_diameter }}</td>
                <td>{{ row.launch }}</td>
                <td>{{ row.spin }}</td>
              </tr>
            {% endfor %}
          </tbody>
        </table>
      </div>
      {% if shaft_table.image %}
        <div class="shaft-specs__media">
          <div class="shaft-specs__image-wrap">
            {{ shaft_table.image
              | image_url: width: 1400
              | image_tag: loading: 'lazy', alt: table_title, class: 'shaft-specs__image'
            }}
          </div>
          {% if shaft_table.image_caption != blank %}
            <div class="shaft-specs__caption">{{ shaft_table.image_caption }}</div>
          {% endif %}
        </div>
      {% endif %}
      {% if shaft_table.footnote != blank %}
        <div class="shaft-specs__footnote">{{ shaft_table.footnote }}</div>
      {% endif %}
    </section>
  {% endfor %}
{% endif %}

